let p = [];
let mySize, margin;
let seed = Math.random() * 9999;
let palette;

function setup() {
	frameRate(50);
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight) * 0.8;
	margin = mySize / 100;
	createCanvas(mySize, mySize);
	for (let i = 0; i < mySize * random([20, 30, 40]); i++) {
		p[i] = createVector(random(-width * 0.2, width * 1.2), random(-height * 0.2, height * 1.2));
	}
	palette = random(colorScheme).colors.concat();

	background(random(palette));
	makeFilter();
	makeFilter2();
}

function draw() {
	randomSeed(seed);
	if (frameCount == 1) {
		background(random(palette));
	}
	image(overAllTexture2, 0, 0);
	makePar();
	if (frameCount > 200) {
		// p.clear();
		seed = Math.random() * 99999;
		randomSeed(seed);
		for (let i = 0; i < mySize * random([20, 30, 40]); i++) {
			p[i] = createVector(random(-width * 0.2, width * 1.2), random(-height * 0.2, height * 1.2));
		}
		image(overAllTexture2, 0, 0);
		makePar();
		frameCount = 0;
	}

	image(overAllTexture2, 0, 0);
	noFill();
	stroke("#202020");
	strokeWeight(margin);
	drawingContext.setLineDash([0, 0]);
	rect(0, 0, width, height);
}

function makePar() {
	let rio = random(500, 10);
	let angle = random(TAU);
	for (let newp of p) {
		let b1 = noise(newp.x / rio, newp.y / rio) * TWO_PI;
		let c = random(1, 100);
		b2 = sin(TWO_PI / c) * int((b1 / TWO_PI) * c);
		newp.add(sin(b2), cos(b2));
		noStroke();
		fill(0);
		push();
		translate(newp.x, newp.y);
		let gard_w = random(6, 2);
		let gard_h = gard_w * random(0.1, 2);
		if (b1 < 1.75) {
			let grad = drawingContext.createLinearGradient(0, 0, gard_w, gard_h);
			grad.addColorStop(0, str(palette[0]) + "00");
			grad.addColorStop(1, str(random(palette)) + "00");
			drawingContext.fillStyle = grad;
		} else if (b1 > 1.75 && b1 < 2.25) {
			var grad = drawingContext.createLinearGradient(0, 0, gard_w, gard_h);
			grad.addColorStop(0, palette[1]);
			grad.addColorStop(1, str(random(palette)) + "40");
			drawingContext.fillStyle = grad;
		} else if (b1 > 2.25 && b1 < 2.75) {
			drawingContext.shadowColor = "#202020";
			drawingContext.shadowOffsetX = 1;
			drawingContext.shadowOffsetY = 1;
			drawingContext.shadowBlur = 20;
			var grad = drawingContext.createLinearGradient(0, 0, gard_w, gard_h);
			grad.addColorStop(0, palette[2]);
			grad.addColorStop(1, str(random(palette)) + "40");
			drawingContext.fillStyle = grad;
		} else if (b1 > 3 && b1 < 3.75) {
			var grad = drawingContext.createLinearGradient(0, 0, gard_w, gard_h);
			grad.addColorStop(0, str(palette[3]) + "00");
			grad.addColorStop(1, str(random(palette)) + "00");
			drawingContext.fillStyle = grad;
		} else {
			drawingContext.shadowColor = random(palette);
			drawingContext.shadowOffsetX = 1;
			drawingContext.shadowOffsetY = 1;
			drawingContext.shadowBlur = 10;
			var grad = drawingContext.createLinearGradient(0, 0, gard_w, gard_h);
			grad.addColorStop(0, random(palette));
			grad.addColorStop(1, str(random(palette)) + "00");
			drawingContext.fillStyle = grad;
		}
		rotate(b1 + angle + PI / 24 * int(random(24)));
		rect(0, 0, gard_w, gard_h);
		pop();
	}
}

